# Let me try a completely different approach.
# Let me manually trace which 0s become 1 by checking their neighborhood

# For each 0 in the input, check if ALL 8 neighbors are 3. If so, maybe it becomes 1?
print("Checking if isolated 0s (surrounded by 3s) become 1:")
for r in range(26):
    for c in range(11):
        if demo_input[r][c] == 0:
            # Check 8-neighborhood
            neighbors = []
            for dr in [-1, 0, 1]:
                for dc in [-1, 0, 1]:
                    if dr == 0 and dc == 0:
                        continue
                    nr, nc = r + dr, c + dc
                    if 0 <= nr < 26 and 0 <= nc < 11:
                        neighbors.append(demo_input[nr][nc])

            all_three = all(n == 3 for n in neighbors)
            became_one = demo_output[r][c] == 1
            print(f"({r},{c}): input=0, all_neighbors=3={all_three}, became_1={became_one}")

# Cleaner view of which cells became 1
all_became_1 = set()
for r in range(26):
    for c in range(11):
        if demo_input[r][c] == 0 and demo_output[r][c] == 1:
            all_became_1.add((r,c))

print("All positions that became 1:")
for r, c in sorted(all_became_1):
    print(f"({r:2d},{c:2d})")

print("\n\nOrganized by column (rows that became 1):")
from itertools import groupby
for c in range(11):
    rows = [r for r, cc in all_became_1 if cc == c]
    if rows:
        print(f"Col {c}: {sorted(rows)}")

# Let me think about this from the perspective of "regions"
# The input has walls (3s) and empty space (0s)
# Maybe the 1s fill regions that "connect" to the seed in some way

# Let me identify horizontal segments of 0s in each row
print("Horizontal segments of consecutive 0s in each row:")
for r in range(26):
    row_input = demo_input[r]
    segments = []
    start = None
    for c in range(11):
        if row_input[c] == 0 and start is None:
            start = c
        elif row_input[c] != 0 and start is not None:
            segments.append((start, c-1))
            start = None
    if start is not None:
        segments.append((start, 10))

    if segments:
        print(f"Row {r}: {segments}")

# Now let me check which segments have cells that become 1
print("\n\nWhich segments get filled with 1s?")
for r in range(26):
    row_input = demo_input[r]

    # Find 0 segments
    segments = []
    start = None
    for c in range(11):
        if row_input[c] == 0 and start is None:
            start = c
        elif row_input[c] != 0 and start is not None:
            segments.append((start, c-1))
            start = None
    if start is not None:
        segments.append((start, 10))

    if segments:
        # Check what parts of each segment became 1
        filled_in_segment = []
        for start, end in segments:
            for c in range(start, end+1):
                if demo_output[r][c] == 1:
                    filled_in_segment.append((start, c))
                elif demo_output[r][c] == 0 and filled_in_segment:
                    # Break - segment untouched
                    break
        if filled_in_segment:
            print(f"Row {r}: segment {(start,end) if 'start' in locals() else '?'} -> {filled_in_segment}")

# Testing: positions that became 1 are those where r%2 == c%2

print("Testing (r+c)%2 == 0 pattern for ALL cells that became 1:")
all_correct = True
all_correct_regions = []

for r in range(26):
    for c in range(11):
        if demo_input[r][c] == 0 and demo_output[r][c] == 1:
            # This cell became 1, check if (r+c)%2 == 0
            matches = (r + c) % 2 == 0
            if not matches:
                all_correct = False
            print(f"({r:2d},{c:2d}): match={matches}")

# Count matches
print(f"\nAll {len(all_became_1)} cells match: {all_correct}")

# But wait - maybe it's more nuanced
# What if BOTH r%2==c%2 is required AND there's another condition?

# Let me check: what about cells that have r%2==c%2 but stayed 0?
print("\n\nCells with r%2==c%2 but stayed 0:")
stayed_0 = []
for r in range(26):
    for c in range(11):
        if demo_input[r][c] == 0 and (r + c) % 2 == 0:
            if demo_output[r][c] == 0:
                stayed_0.append((r, c))
for (r, c) in stayed_0:
    print(f"({r},{c}): r%2={r%2}, c%2={c%2}, (r+c)%2=0, but output={demo_output[r][c]}")

# So it's not just r%2==c%2...
# There must be additional constraints. Let me think about which regions to fill.

# Let me redo the diagonal and distance analysis
seeds = [(20,6), (20,10), (21,7), (21,8), (21,10), (22,8), (22,9), (23,8), (23,9)]

print("Diagonal analysis - where 1s appear relative to seeds:")

# Check (r - c) values for cells that became 1
diff_values = sorted(set(r - c for (r, c) in all_became_1))
print(f"Difference (r-c) values for 1s: {diff_values}")
print(f"  Seed (r-c) values: {sorted(r-c for r, c in seeds)}")

# Check (r + c) values for cells that became 1
sum_values = sorted(set(r + c for (r, c) in all_became_1))
print(f"Sum (r+c) values for 1s: {sum_values}")
print(f"  Seed (r+c) values: {sorted(r+c for r, c in seeds)}")

# Check (r + c) % 4 pattern
from collections import Counter
sum_counts = Counter(r + c for (r, c) in all_became_1)
print("\n(r+c) mod 4 distribution for 1s:")
for mod in [0, 1, 2, 3]:
    count = sum(1 for s in sum_counts if s % 4 == mod)
    print(f"  (r+c) % 4 = {mod}: count = {count}")

# Now let's analyze distances more carefully
print("\n\nManhattan distance analysis:")
all_dists = {}
for r in range(26):
    for c in range(11):
        if demo_input[r][c] == 0:
            dists = [abs(r - sr) + abs(c - sc) for sr, sc in seeds]
            d = min(dists)
            all_dists[(r, c)] = d

# Group cells by which distance bin they fall into
dist_bins = {
    '0-5': [],
    '6-10': [],
    '11-15': [],
    '16-20': [],
    '21-26': []
}

for (r, c), d in all_dists.items():
    if demo_output[r][c] == 1:
        dist_bins[f'16-20'].append(None)  # Add to appropriate bin later
    # Filled with actual cells
    if demo_output[r][c] == 1:
        for key in dist_bins:
            if len(dist_bins[key]) == 0:
                if (d >= 0 and d <= 5):
                    dist_bins[key].append((r, c))
                elif (d >= 6 and d <= 10):
                    dist_bins[key].append((r, c))
                elif (d >= 11 and d <= 15):
                    dist_bins[key].append((r, c))
                elif (d >= 16 and d <= 20):
                    dist_bins[key].append((r, c))
                elif (d >= 21 and d <= 26):
                    dist_bins[key].append((r, c))

print("Distance bins for 1s:")
for (key, cells) in dist_bins.items():
    print(f"  {key}: {len(cells)} cells")

# Better approach - just print all distances for 1s
became_1_dists = [(r, c, all_dists[(r,c)]) for (r, c), d in all_dists.items() if demo_output[r][c] == 1]
became_1_dists.sort(key=lambda x: x[2])
print(f"\n1s sorted by distance: {became_1_dists}")

